        s.text(0.75, 3.15, 8.0, 1.9, "Total daily protein predicted muscle gain best. Timing alone added little.", { font: "light", size: 28, lineH: 1.15 });
        s.text(0.75, 4.75, 8.0, 1.2, "And one college team ate less than recommended for energy, carbs and protein.", { font: "light", size: 22, color: "muted", lineH: 1.2 });
