        s.rect(X(11), top, X(14) - X(11), base - top, { fill: "soft" });
        s.rect(X(17), top, X(19) - X(17), base - top, { fill: "soft" });
        s.rect(X(15), top, X(17) - X(15), base - top, { line: "accent", lineW: 2.5 });
        s.line(X(9), base, X(21), base, { color: "muted", w: 1.5 });
        [[9, "9 AM"], [12, "Noon"], [15, "3 PM"], [18, "6 PM"], [21, "9 PM"]].forEach(([h, t]) => {
          s.line(X(h), base, X(h), base + 0.12, { color: "muted", w: 1 });
          s.label(t, { x: X(h) - 0.8, y: base + 0.2, w: 1.6, align: "center", size: 14 });
        });
        const win = [
          [11, 14, "Before", "A meal 1–4 h out", "muted"],
          [15, 17, "During", "Carbs if it runs past an hour", "accent"],
          [17, 19, "After", "Protein within about 2 h", "muted"],
        ];
        win.forEach(([a, b, k, t, c]) => {
          s.label(k, { x: X(a) + 0.15, y: top + 0.18, w: X(b) - X(a) - 0.3, color: c, size: 15 });
          s.text(X(a) + 0.15, top + 0.6, X(b) - X(a) - 0.3, 1.3, t, { font: "light", size: 20, lineH: 1.15 });
        });
        s.text(X(19) + 0.2, base - 0.85, 2.0, 0.75, "Illustrative day, times are examples", { font: "light", size: 13, color: "muted", lineH: 1.1 });
        s.source("Thomas, Erdman & Burke 2016 · Kerksick et al. 2017", { y: 6.2, refs: ["thomas2016", "kerksick2017"] });
        s.cite("kerksick2008");
      },
    },
    {
      role: "application", time: 60,
      notes: `Here is how that plays out on our calendar. Two situations come up every week.

When the session is early and there is no time for a meal, the answer is not to skip it. Something light and easy on the stomach on the way in, then a real breakfast after. The position stand's advice is to keep high-fat and high-fiber foods away from right before training.

When there are two sessions less than eight hours apart, refuel right after the first: carbohydrate with some protein, not just water and a wait.

The exact amounts belong to the sports dietitian, because they depend on the athlete. Our job is to make sure the schedule leaves room to eat.`,
      build(s) {
        s.headline("Match the food to the schedule.", { y: 1.2, w: 11.5, h: 0.9, size: 44 });
        const c1 = 0.75, c2 = 6.2;
        s.label("When", { x: c1, y: 2.55, w: 3 });
        s.label("Do", { x: c2, y: 2.55, w: 3 });
        s.line(0.75, 2.98, 12.58, 2.98, { color: "rule", w: 1 });
        const rows = [
          ["Early session, no time for a meal", "Something light before, a real breakfast after"],
          ["Two sessions less than 8 h apart", "Carbs and protein right after the first"],
        ];
        rows.forEach(([w, d], i) => {
          const y = 3.2 + i * 1.5;
          s.text(c1, y, 5.0, 1.1, w, { font: "light", size: 26, lineH: 1.12 });
          s.text(c2, y, 6.3, 1.1, d, { font: "medium", size: 26, lineH: 1.12 });
          s.line(0.75, y + 1.3, 12.58, y + 1.3, { color: "rule", w: 1 });
        });
        s.source("Thomas, Erdman & Burke 2016", { y: 6.2, refs: ["thomas2016"] });
      },
    },
    {
      role: "takeaway", time: 45,
      notes: `The line to take away: feed the day, then time it. Most of the benefit comes from athletes eating enough, regularly. Timing is the refinement on top, and it matters most on long days and short turnarounds.

Question for the room: where in our schedule do athletes train on empty? Early lifts, class running into practice, the bus leaving before the meal is ready. The answers tend to be specific, and most of them are scheduling problems we can actually fix.`,
      build(s) {
        s.headline("Feed the day. Then time it.", { y: 1.3, w: 7.5, h: 2.2, size: 72 });
        s.text(6.1, 4.25, 6.48, 1.9, "Where in our schedule do athletes train on empty?", { font: "medium", size: 34, color: "accent", lineH: 1.12, align: "right" });
      },
    },
  ],
};

